import unittest

import rosterkit.contacts
import rosterkit.errors
import rosterkit.models


# ---
def student(student_id, last_name, first_name, email):
    return rosterkit.models.Student(student_id, last_name, first_name, "A", email)


class ContactRowTests(unittest.TestCase):
    def test_rows_are_sorted_by_name(self):
        students = [
            student("1002", "Varrow", "Ines", "ivarrow@example.edu"),
            student("1003", "Quillon", "Sefa", "sq@example.invalid"),
        ]
        rows = rosterkit.contacts.contact_rows(students)
        self.assertTrue(
            rows
            == [
                "Quillon, Sefa            A        sq@example.invalid",
                "Varrow, Ines             A        ivarrow@example.edu",
            ]
        )

    def test_missing_email_names_the_student(self):
        students = [student("1001", "Thistle", "Bram", None)]
        with self.assertRaises(rosterkit.errors.ProjectError) as caught:
            rosterkit.contacts.contact_rows(students)
        self.assertTrue("Thistle, Bram" in str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(rosterkit.errors.ProjectError):
            rosterkit.contacts.contact_rows([])
